changeSet.sql:
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables
               WHERE table_schema = 'user' AND table_name = 'blog')
     AND NOT EXISTS (SELECT 1 FROM information_schema.tables
               WHERE table_schema = 'user' AND table_name = 'news') THEN
    ALTER TABLE "user".blog RENAME TO news;
  END IF;
END $$;
